//! Chrome wording for every Settings language except Arabic and English.
//!
//! Row order is [`super::ChromeKey::ALL`]. Tags outside this list fall
//! back to Arabic. Turkish is Latin script and left to right.

pub(super) fn localized(tag: &str, key: super::ChromeKey) -> Option<&'static str> {
    let index = super::ChromeKey::ALL.iter().position(|item| *item == key)?;
    let row = CATALOGS.iter().find(|catalog| catalog.tag == tag)?;
    row.strings.get(index).copied()
}

struct Catalog {
    tag: &'static str,
    strings: &'static [&'static str; WIDTH],
}

const WIDTH: usize = 89;
const _: [(); WIDTH] = [(); super::ChromeKey::ALL.len()];

